<script>
// ─────────────────────────────────────────────────────────────────────────────
// COIN RENDERER — pure 2D Canvas, no external deps
// ─────────────────────────────────────────────────────────────────────────────

// Coin parameters
const COIN_TYPES = {
  hero:   { r: 170, front: {primary:'#d4af78',mid:'#e8cb99',hi:'#fff8e8',dark:'#8a6a30',rim:'#b8922a'}, back: {primary:'#c8a060',mid:'#ddb870',hi:'#f5e0a0',dark:'#7a5820',rim:'#a87828'}, label:'WASTED\nTOKEN', denom:'10,000\nTOKENS' },
  bronze: { r: 64,  front: {primary:'#b87333',mid:'#d4924a',hi:'#f0c080',dark:'#6b3e1a',rim:'#8b5020'}, back: {primary:'#a06828',mid:'#c08040',hi:'#e0a060',dark:'#5a3010',rim:'#7a4018'}, label:'BRONZE', denom:'1,000\nTOKENS' },
  silver: { r: 64,  front: {primary:'#c0c8d8',mid:'#dde4f0',hi:'#ffffff',dark:'#6878a0',rim:'#8898b8'}, back: {primary:'#b0b8cc',mid:'#ccd4e4',hi:'#f0f4ff',dark:'#5868a0',rim:'#7888b0'}, label:'SILVER', denom:'5,000\nTOKENS' },
  gold:   { r: 64,  front: {primary:'#d4a830',mid:'#f0cc60',hi:'#fff4a0',dark:'#806010',rim:'#a07820'}, back: {primary:'#c89820',mid:'#e0b840',hi:'#fff080',dark:'#705008',rim:'#906810'}, label:'GOLD', denom:'25,000\nTOKENS' },
  black:  { r: 64,  front: {primary:'#202028',mid:'#383848',hi:'#6868a0',dark:'#080810',rim:'#303040'}, back: {primary:'#181820',mid:'#2a2a38',hi:'#5050a0',dark:'#040408',rim:'#282830'}, label:'OBSIDIAN', denom:'100,000\nTOKENS' },
};

// Draw a coin at a specific animation time t ∈ [0,1]
// Returns the canvas context (already drawn)
function drawCoin(ctx, cx, cy, coinType, t) {
  const cfg = COIN_TYPES[coinType];
  const R = cfg.r;

  // Animation: t goes 0→1
  // Rotation about Y (horizontal angle for x-scale): full 360
  // Flip about X: one complete flip during the loop, tied to Y rotation
  const angleY = t * Math.PI * 2; // 0 to 2π
  const angleX = t * Math.PI * 2; // same pace for flip

  // xScale: cosine of Y rotation → determines coin width (edge-on at 90°/270°)
  const xScale = Math.cos(angleY);
  // yScale: cosine of X rotation for tilt
  const yTilt = Math.cos(angleX) * 0.12; // subtle tilt
  const yScale = 1.0 + yTilt;

  // Determine face: front (xScale > 0), back (xScale < 0), edge (≈0)
  const absX = Math.abs(xScale);
  const isEdge = absX < 0.08;
  const isFront = xScale >= 0;

  const face = isFront ? cfg.front : cfg.back;
  const effectiveR = Math.max(R * absX, isEdge ? 4 : 1);

  // Specular position: rakes across as coin rotates
  // angleY maps specular to move left→right→left
  const specX = cx + Math.sin(angleY) * R * 0.55;
  const specY = cy - R * 0.25;

  // ─── EDGE / REEDING STRIPS ───
  if (absX < 0.98) {
    const edgeW = R * 2 * (1 - absX);
    const edgeH = R * 2 * yScale;
    const numReeds = Math.max(2, Math.floor(40 * (1-absX)));

    // Edge color based on face
    const rimGrad = ctx.createLinearGradient(cx - edgeW/2, cy, cx + edgeW/2, cy);
    rimGrad.addColorStop(0, face.dark);
    rimGrad.addColorStop(0.4, face.rim);
    rimGrad.addColorStop(1, face.dark);

    // Draw reeded edge strips
    for (let i = 0; i < numReeds; i++) {
      const yOff = (i / numReeds - 0.5) * edgeH;
      const reedH = edgeH / numReeds;
      const brightness = (i % 2 === 0) ? 1.0 : 0.55;
      ctx.beginPath();
      ctx.rect(cx - edgeW/2, cy + yOff, edgeW, reedH * 0.9);
      ctx.fillStyle = (i % 2 === 0) ? face.rim : face.dark;
      ctx.globalAlpha = 0.9;
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  // ─── COIN FACE ───
  if (!isEdge) {
    const faceW = effectiveR;
    const faceH = R * yScale;

    // Background field gradient
    const grad = ctx.createLinearGradient(cx - faceW, cy - faceH, cx + faceW, cy + faceH);
    grad.addColorStop(0, face.dark);
    grad.addColorStop(0.3, face.primary);
    grad.addColorStop(0.6, face.mid);
    grad.addColorStop(1, face.dark);

    ctx.save();
    ctx.beginPath();
    ctx.ellipse(cx, cy, faceW, faceH, 0, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();

    // Clip to coin face for all face elements
    ctx.beginPath();
    ctx.ellipse(cx, cy, faceW, faceH, 0, 0, Math.PI * 2);
    ctx.clip();

    // ─── FACE CONTENT ───
    if (isFront) {
      drawFrontFace(ctx, cx, cy, faceW, faceH, cfg, face, coinType);
    } else {
      drawBackFace(ctx, cx, cy, faceW, faceH, cfg, face, coinType);
    }

    // ─── SPECULAR HIGHLIGHT ───
    // Moving specular rake
    const specXLocal = specX;
    const specW = faceW * 0.6;
    const specH = faceH * 0.5;

    const specGrad = ctx.createRadialGradient(specXLocal, specY, 0, specXLocal, specY, specW);
    specGrad.addColorStop(0, 'rgba(255,255,240,0.55)');
    specGrad.addColorStop(0.3, 'rgba(255,255,220,0.18)');
    specGrad.addColorStop(1, 'rgba(255,255,200,0)');

    ctx.beginPath();
    ctx.ellipse(specXLocal, specY, specW, specH, 0, 0, Math.PI * 2);
    ctx.fillStyle = specGrad;
    ctx.fill();

    // Secondary rim specular
    const rimSpec = ctx.createRadialGradient(cx, cy, faceW * 0.7, cx, cy, faceW);
    rimSpec.addColorStop(0, 'rgba(255,255,255,0)');
    rimSpec.addColorStop(0.85, 'rgba(255,255,220,0.12)');
    rimSpec.addColorStop(1, 'rgba(255,255,200,0.35)');
    ctx.beginPath();
    ctx.ellipse(cx, cy, faceW, faceH, 0, 0, Math.PI * 2);
    ctx.fillStyle = rimSpec;
    ctx.fill();

    ctx.restore();

    // ─── RIM RING ───
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(cx, cy, faceW, faceH, 0, 0, Math.PI * 2);
    ctx.lineWidth = Math.max(2, faceW * 0.05);
    const rimGrad2 = ctx.createLinearGradient(cx - faceW, cy - faceH, cx + faceW, cy + faceH);
    rimGrad2.addColorStop(0, face.dark);
    rimGrad2.addColorStop(0.4, face.hi);
    rimGrad2.addColorStop(0.7, face.mid);
    rimGrad2.addColorStop(1, face.dark);
    ctx.strokeStyle = rimGrad2;
    ctx.stroke();
    ctx.restore();
  }
}

function drawFrontFace(ctx, cx, cy, fw, fh, cfg, face, coinType) {
  const R = cfg.r;
  const scale = fw / R;

  // Outer ring
  ctx.beginPath();
  ctx.ellipse(cx, cy, fw * 0.92, fh * 0.92, 0, 0, Math.PI*2);
  ctx.strokeStyle = face.hi;
  ctx.lineWidth = scale * 2;
  ctx.globalAlpha = 0.4;
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.beginPath();
  ctx.ellipse(cx, cy, fw * 0.88, fh * 0.88, 0, 0, Math.PI*2);
  ctx.strokeStyle = face.mid;
  ctx.lineWidth = scale * 1;
  ctx.globalAlpha = 0.3;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Central emblem — draw a stylised "W" shield / emblem
  if (coinType === 'hero') {
    drawHeroEmblem(ctx, cx, cy, scale, face, fw, fh);
  } else {
    drawMiniEmblem(ctx, cx, cy, scale, face, fw, fh, coinType);
  }

  // Coin label text around top arc
  const labelText = cfg.label || 'WASTEDTOKEN';
  const lines = labelText.split('\n');
  const fontSize = Math.max(6, scale * (coinType === 'hero' ? 11 : 9));

  if (coinType === 'hero') {
    // Arc text at top
    drawArcText(ctx, cx, cy, fw * 0.78, fh * 0.78, 'WASTED TOKEN MINT', fontSize * 0.9, -Math.PI * 0.75, Math.PI * 0.75, face.hi, scale);
    // Year at bottom
    drawArcText(ctx, cx, cy, fw * 0.78, fh * 0.78, '✦ MMXXIII ✦', fontSize * 0.85, Math.PI * 0.25, Math.PI * 0.75, face.mid, scale, true);
  } else {
    const fs = Math.max(5, scale * 8);
    ctx.font = `bold ${fs}px Georgia, serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = face.hi;
    ctx.globalAlpha = 0.9;
    lines.forEach((line, i) => {
      ctx.fillText(line, cx, cy - fh * 0.35 + i * fs * 1.2);
    });
    ctx.globalAlpha = 1;
  }
}

function drawHeroEmblem(ctx, cx, cy, scale, face, fw, fh) {
  const s = scale;
  // Decorative outer star points
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const r1 = fw * 0.62;
    const r2 = fw * 0.68;
    const x1 = cx + Math.cos(a) * r1;
    const y1 = cy + Math.sin(a) * r1 * (fh/fw);
    const x2 = cx + Math.cos(a) * r2;
    const y2 = cy + Math.sin(a) * r2 * (fh/fw);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = face.hi;
    ctx.lineWidth = s * 1.5;
    ctx.globalAlpha = 0.5;
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // Inner circle with gradient
  const innerR = fw * 0.45;
  const innerGrad = ctx.createRadialGradient(cx - innerR*0.3, cy - innerR*0.3, 0, cx, cy, innerR);
  innerGrad.addColorStop(0, face.mid);
  innerGrad.addColorStop(0.6, face.primary);
  innerGrad.addColorStop(1, face.dark);
  ctx.beginPath();
  ctx.ellipse(cx, cy, innerR, innerR * (fh/fw), 0, 0, Math.PI*2);
  ctx.fillStyle = innerGrad;
  ctx.fill();

  // W letterform — stylised
  const wSize = fw * 0.28;
  const wx = cx;
  const wy = cy;
  ctx.save();
  ctx.font = `bold ${wSize}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Shadow
  ctx.fillStyle = face.dark;
  ctx.fillText('W', wx + s*1, wy + s*1.5);

  // Main letter
  const letterGrad = ctx.createLinearGradient(wx, wy - wSize/2, wx, wy + wSize/2);
  letterGrad.addColorStop(0, face.hi);
  letterGrad.addColorStop(0.4, face.mid);
  letterGrad.addColorStop(1, face.primary);
  ctx.fillStyle = letterGrad;
  ctx.fillText('W', wx, wy);
  ctx.restore();

  // Raised dots decorating inner ring
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    const dr = fw * 0.52;
    const dx = cx + Math.cos(a) * dr;
    const dy = cy + Math.sin(a) * dr * (fh/fw);
    ctx.beginPath();
    ctx.arc(dx, dy, s * 1.5, 0, Math.PI*2);
    ctx.fillStyle = i % 3 === 0 ? face.hi : face.mid;
    ctx.globalAlpha = 0.6;
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawMiniEmblem(ctx, cx, cy, scale, face, fw, fh, coinType) {
  const s = scale;
  const innerR = fw * 0.45;

  // Inner circle
  const innerGrad = ctx.createRadialGradient(cx - innerR*0.3, cy - innerR*0.3, 0, cx, cy, innerR);
  innerGrad.addColorStop(0, face.mid);
  innerGrad.addColorStop(1, face.dark);
  ctx.beginPath();
  ctx.ellipse(cx, cy, innerR, innerR * (fh/fw), 0, 0, Math.PI*2);
  ctx.fillStyle = innerGrad;
  ctx.fill();

  // Small W
  const wSize = fw * 0.30;
  ctx.font = `bold ${wSize}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  ctx.fillStyle = face.dark;
  ctx.fillText('W', cx + s*0.5, cy + s);

  const lg = ctx.createLinearGradient(cx, cy - wSize/2, cx, cy + wSize/2);
  lg.addColorStop(0, face.hi);
  lg.addColorStop(1, face.mid);
  ctx.fillStyle = lg;
  ctx.fillText('W', cx, cy);

  // Dots
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * Math.PI * 2;
    const dr = fw * 0.52;
    const dx = cx + Math.cos(a) * dr;
    const dy = cy + Math.sin(a) * dr * (fh/fw);
    ctx.beginPath();
    ctx.arc(dx, dy, s * 1.2, 0, Math.PI*2);
    ctx.fillStyle = i % 2 === 0 ? face.hi : face.mid;
    ctx.globalAlpha = 0.55;
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawBackFace(ctx, cx, cy, fw, fh, cfg, face, coinType) {
  const R = cfg.r;
  const scale = fw / R;
  const denom = cfg.denom || '10,000\nTOKENS';

  // Outer rings
  ctx.beginPath();
  ctx.ellipse(cx, cy, fw * 0.90, fh * 0.90, 0, 0, Math.PI*2);
  ctx.strokeStyle = face.hi;
  ctx.lineWidth = scale * 2.5;
  ctx.globalAlpha = 0.35;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Inner decorative ring pattern — crosshatch / guilloche style
  const numLines = coinType === 'hero' ? 18 : 10;
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx, cy, fw * 0.82, fh * 0.82, 0, 0, Math.PI*2);
  ctx.clip();

  for (let i = 0; i < numLines; i++) {
    const a = (i / numLines) * Math.PI;
    ctx.beginPath();
    ctx.moveTo(cx - Math.cos(a) * fw * 0.82, cy - Math.sin(a) * fh * 0.82);
    ctx.lineTo(cx + Math.cos(a) * fw * 0.82, cy + Math.sin(a) * fh * 0.82);
    ctx.strokeStyle = face.mid;
    ctx.lineWidth = scale * 0.5;
    ctx.globalAlpha = 0.12;
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  ctx.restore();

  // Central raised area
  const centR = fw * 0.6;
  const centGrad = ctx.createRadialGradient(cx, cy - fh*0.1, 0, cx, cy, centR);
  centGrad.addColorStop(0, face.mid);
  centGrad.addColorStop(0.5, face.primary);
  centGrad.addColorStop(1, face.dark);
  ctx.beginPath();
  ctx.ellipse(cx, cy, centR, centR * (fh/fw), 0, 0, Math.PI*2);
  ctx.fillStyle = centGrad;
  ctx.fill();

  // Denomination text
  const lines = denom.split('\n');
  const bigSize = coinType === 'hero' ? fw * 0.22 : fw * 0.20;
  const smallSize = coinType === 'hero' ? fw * 0.10 : fw * 0.09;

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Main number
  ctx.font = `bold ${bigSize}px Georgia, serif`;
  ctx.fillStyle = face.dark;
  ctx.fillText(lines[0], cx + scale*0.8, cy - fh*0.06 + scale);

  const numGrad = ctx.createLinearGradient(cx, cy - bigSize/2, cx, cy + bigSize/2);
  numGrad.addColorStop(0, face.hi);
  numGrad.addColorStop(0.5, face.mid);
  numGrad.addColorStop(1, face.primary);
  ctx.fillStyle = numGrad;
  ctx.fillText(lines[0], cx, cy - fh*0.06);

  // "TOKENS" label
  if (lines[1]) {
    ctx.font = `${smallSize}px Georgia, serif`;
    ctx.fillStyle = face.hi;
    ctx.globalAlpha = 0.85;
    ctx.fillText(lines[1], cx, cy + fh * 0.18);
    ctx.globalAlpha = 1;
  }

  // Mint mark
  if (coinType === 'hero') {
    ctx.font = `${smallSize * 0.7}px Georgia, serif`;
    ctx.fillStyle = face.mid;
    ctx.globalAlpha = 0.7;
    ctx.fillText('WTM ✦ CERTIFIED', cx, cy + fh * 0.38);
    ctx.globalAlpha = 1;
  }
}

function drawArcText(ctx, cx, cy, rx, ry, text, fontSize, startAngle, endAngle, color, scale, bottom = false) {
  const numChars = text.length;
  const totalAngle = endAngle - startAngle;
  const charAngle = totalAngle / Math.max(numChars - 1, 1);

  ctx.save();
  ctx.font = `${fontSize}px Georgia, serif`;
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.globalAlpha = 0.9;

  for (let i = 0; i < numChars; i++) {
    const a = bottom
      ? (startAngle + (numChars - 1 - i) * charAngle + Math.PI)
      : (startAngle + i * charAngle - Math.PI / 2);

    const x = cx + Math.cos(a + (bottom ? 0 : Math.PI/2)) * rx;
    const y = cy + Math.sin(a + (bottom ? 0 : Math.PI/2)) * ry;

    ctx.save();
    ctx.translate(x, y);
    const charA = bottom
      ? (a + Math.PI/2 + Math.PI)
      : (a - Math.PI/2 + Math.PI/2 + Math.PI/2);
    ctx.rotate(charA - Math.PI/2 * (bottom ? -1 : 1) + (bottom ? Math.PI : 0));
    ctx.fillText(text[i], 0, 0);
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  ctx.restore();
}

// Better arc text using standard canvas arc method
function drawArcTextSimple(ctx, cx, cy, rx, ry, text, fontSize, topArc, color) {
  ctx.save();
  ctx.font = `bold ${fontSize}px Georgia, serif`;
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.globalAlpha = 0.85;

  const chars = text.split('');
  const totalSpan = Math.PI * 1.2;
  const step = totalSpan / Math.max(chars.length - 1, 1);
  const startA = topArc ? -totalSpan/2 - Math.PI/2 : Math.PI/2 - totalSpan/2;

  chars.forEach((ch, i) => {
    const a = startA + i * step;
    const x = cx + Math.cos(a) * rx;
    const y = cy + Math.sin(a) * ry;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(a + (topArc ? Math.PI/2 : -Math.PI/2));
    ctx.fillText(ch, 0, 0);
    ctx.restore();
  });
  ctx.globalAlpha = 1;
  ctx.restore();
}

